package com.insectlabs.sn93t;
import java.lang.reflect.*;
import java.nio.file.*;
public final class TnrCoreTest {
 private static final Class<?> C; private static final Constructor<?> CTOR;
 private static final Method PUSH,TICK,TONE,SET_TONE,SET_RANGE,SET_RESPONSE,SET_REF,CAL_START,CAL_STATE,PARSE_TUN,PARSE_SCL;
 private static final Field VALID,HZ,CAL_CV,CAL_SLOPE,CAL_RESID,CAL_GOOD,CAL_TOTAL;
 static { try { C=Class.forName("com.insectlabs.sn93t.sn93t$TnrCore"); CTOR=C.getDeclaredConstructor(); CTOR.setAccessible(true);
  PUSH=C.getMethod("push",double.class); TICK=C.getMethod("tickHop"); TONE=C.getMethod("toneSample"); SET_TONE=C.getMethod("setTone",boolean.class,double.class,double.class);
  SET_RANGE=C.getMethod("setRange",int.class); SET_RESPONSE=C.getMethod("setResponse",double.class); SET_REF=C.getMethod("setRefA4",double.class); CAL_START=C.getMethod("calStart",double.class,double.class,int.class); CAL_STATE=C.getMethod("calState");
  for(Method m:new Method[]{PUSH,TICK,TONE,SET_TONE,SET_RANGE,SET_RESPONSE,SET_REF,CAL_START,CAL_STATE})m.setAccessible(true);
  VALID=C.getField("valid"); HZ=C.getField("hz"); CAL_CV=C.getField("calCv"); CAL_SLOPE=C.getField("calSlopeOctPerV"); CAL_RESID=C.getField("calMaxResidCents"); CAL_GOOD=C.getField("calGoodSteps"); CAL_TOTAL=C.getField("calTotalSteps");
  PARSE_TUN=C.getMethod("parseTun",String.class,String.class); PARSE_SCL=C.getMethod("parseScl",String.class,String.class,int.class);
 } catch(Exception e){throw new ExceptionInInitializerError(e);} }
 static Object make() throws Exception{return CTOR.newInstance();} static void invoke(Method m,Object o,Object...a)throws Exception{m.invoke(o,a);} static double d(Field f,Object o)throws Exception{return f.getDouble(o);} static void ck(boolean b,String s){if(!b)throw new AssertionError(s);}
 static void pitchTests()throws Exception{double[] fs={31,35,65.41,110,220,440,880,1760,2100,2125,2150,2175,2180,2190,2195,2199,2200};for(double f:fs){Object c=make();invoke(SET_RANGE,c,0);invoke(SET_RESPONSE,c,0.0);invoke(SET_REF,c,440.0);double p=0;for(int i=0;i<48000;i++){invoke(PUSH,c,.4*Math.sin(p));p+=2*Math.PI*f/48000;if(p>=2*Math.PI)p-=2*Math.PI;if(i%1200==1199)invoke(TICK,c);}ck(VALID.getBoolean(c),"no pitch for "+f);double got=d(HZ,c), cents=1200*Math.log(got/f)/Math.log(2);ck(Math.abs(cents)<2,"pitch error "+f+"="+cents);System.out.printf("pitch %.2f -> %.5f Hz (%+.3f c)%n",f,got,cents);}}
 static void harmonicTests()throws Exception{double[][] mixes={{.8,.4,.2,.1},{.2,.8,.2,.1},{.1,.7,.5,.2},{.4,0,.5,.2}};for(int n=0;n<mixes.length;n++){Object c=make();invoke(SET_RANGE,c,0);invoke(SET_RESPONSE,c,0.0);double p=0;for(int i=0;i<48000;i++){double y=0;for(int h=1;h<=4;h++)y+=mixes[n][h-1]*Math.sin(h*p);invoke(PUSH,c,y);p+=2*Math.PI*440/48000;if(p>=2*Math.PI)p-=2*Math.PI;if(i%1200==1199)invoke(TICK,c);}ck(VALID.getBoolean(c),"no harmonic pitch for case "+n);double got=d(HZ,c),cent=1200*Math.log(got/440)/Math.log(2);ck(Math.abs(cent)<10,"harmonic pitch error case "+n+"="+cent);System.out.printf("harmonic 440 case %d -> %.4fHz (%+.2fc)%n",n,got,cent);}} static void holdAndLossTests()throws Exception{Object c=make();invoke(SET_RANGE,c,0);for(int i=0;i<48000;i++){invoke(PUSH,c,0.0);if(i%1200==1199)invoke(TICK,c);}ck(!VALID.getBoolean(c),"silence produced a pitch");double p=0;for(int i=0;i<48000;i++){invoke(PUSH,c,.4*Math.sin(p));p+=2*Math.PI*440/48000;if(p>=2*Math.PI)p-=2*Math.PI;if(i%1200==1199)invoke(TICK,c);}ck(VALID.getBoolean(c),"440Hz acquisition failed");invoke(C.getMethod("setHold",boolean.class),c,true);for(int i=0;i<48000;i++){invoke(PUSH,c,0.0);if(i%1200==1199)invoke(TICK,c);}ck(VALID.getBoolean(c),"HOLD did not retain last reading");invoke(C.getMethod("setHold",boolean.class),c,false);for(int i=0;i<48000;i++){invoke(PUSH,c,0.0);if(i%1200==1199)invoke(TICK,c);}ck(!VALID.getBoolean(c),"signal-loss timeout did not clear stale reading");Object fine=make();invoke(SET_RANGE,fine,0);invoke(SET_RESPONSE,fine,1.0);p=0;for(int i=0;i<48000;i++){invoke(PUSH,fine,.4*Math.sin(p));p+=2*Math.PI*440/48000;if(p>=2*Math.PI)p-=2*Math.PI;if(i%1200==1199)invoke(TICK,fine);}ck(VALID.getBoolean(fine)&&Math.abs(1200*Math.log(d(HZ,fine)/440)/Math.log(2))<1,"fine response stability failed");System.out.println("silence gate, acquisition, HOLD, signal-loss timeout, fine response: PASS");} static void toneRobustness()throws Exception{Object c=make();invoke(SET_TONE,c,true,440.0,5.0);double peak=0,sum=0,prev=0;int crossings=0;for(int i=0;i<48000;i++){double y=(double)TONE.invoke(c);ck(Double.isFinite(y),"nonfinite tone");peak=Math.max(peak,Math.abs(y));sum+=y*y;if(prev<=0&&y>0)crossings++;prev=y;}ck(peak>4.9&&peak<=5,"tone endpoint "+peak);ck(crossings>=438&&crossings<=442,"tone pitch "+crossings);for(double x:new double[]{Double.NaN,Double.POSITIVE_INFINITY,Double.NEGATIVE_INFINITY})invoke(PUSH,c,x);for(int i=0;i<24000;i++){invoke(PUSH,c,0.0);if(i%1200==1199)invoke(TICK,c);}System.out.printf("tone finite, 5V endpoint, 440Hz: PASS (peak=%.6f, cycles=%d, RMS=%.4f)%n",peak,crossings,Math.sqrt(sum/48000));}
 static void tuningTests(Path folder)throws Exception{for(String name:new String[]{"Harry_Partch_43-tone_G1.tun","Wendy_Carlos_Alpha_78c.tun","Werckmeister_III.tun"}){Object t=PARSE_TUN.invoke(null,Files.readString(folder.resolve(name)),name);ck(t!=null,"parse failed "+name);double[] cents=(double[])t.getClass().getField("cents").get(t);ck(cents.length==128,"bad tun table size");System.out.println("AnaMark .tun parse: PASS "+name+" (128 entries)");}String scl="""
SCL smoke test
! comment
5
!
200.0
400.0
700.0
900.0
2/1
""";Object t=PARSE_SCL.invoke(null,scl,"smoke",0);ck(t!=null,"valid SCL rejected");System.out.println("Scala .scl parse: PASS");}
 static void calibrationTest()throws Exception{Object c=make();invoke(SET_RANGE,c,0);invoke(SET_RESPONSE,c,0.0);invoke(CAL_START,c,0.0,1.0,7);double p=0;for(int i=0;i<48000*8&&(int)CAL_STATE.invoke(c)!=3&&(int)CAL_STATE.invoke(c)!=4;i++){double f=65.41*Math.pow(2,d(CAL_CV,c));invoke(PUSH,c,.4*Math.sin(p));p+=2*Math.PI*f/48000;if(p>=2*Math.PI)p-=2*Math.PI;if(i%1200==1199)invoke(TICK,c);}int state=(int)CAL_STATE.invoke(c);ck(state==3,"CAL state "+state);int good=CAL_GOOD.getInt(c),total=CAL_TOTAL.getInt(c);double slope=d(CAL_SLOPE,c),resid=d(CAL_RESID,c);ck(total==7,"CAL total "+total);ck(good>=5&&good<total,"CAL range filtering "+good+"/"+total);ck(Math.abs(slope-1)<.01,"CAL slope "+slope);ck(resid<3,"CAL residual "+resid);System.out.printf("CAL 7-step synthetic 1V/oct VCO: %.6f oct/V, %.3fc residual, retained %d/%d%n",slope,resid,good,total);}
 public static void main(String[] a)throws Exception{Path p=Path.of(a[0]);pitchTests();harmonicTests();holdAndLossTests();toneRobustness();tuningTests(p);calibrationTest();System.out.println("ALL TNR CORE CHECKS PASSED");}
}